<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $invoice->number }}</title><style>body{font-family:Arial,sans-serif;margin:40px;color:#172033}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border-bottom:1px solid #dbe2ea;padding:10px;text-align:left}th:last-child,td:last-child{text-align:right}.total{text-align:right;margin-top:20px;font-size:18px}</style></head><body><h1>Sales Invoice</h1><p><strong>{{ $invoice->number }}</strong><br>{{ $invoice->customer?->name }}</p><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->variant_id }}</td><td>{{ $item->quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->line_total }}</td></tr>@endforeach</tbody></table><p class="total">Total: {{ $invoice->total }}<br>Paid: {{ $invoice->paid_total }}<br>Balance: {{ bcsub((string)$invoice->total,(string)$invoice->paid_total,6) }}</p></body></html>
